                break

        if targets:
            best = min(targets, key=lambda c: manhattan(c, self_pos))
            return step_toward(self_pos, best)

        enemy = get_xy_list(observation.get("opponent_territory", []))
        if enemy:
            best = min(enemy, key=lambda c: manhattan(c, self_pos))
            return step_toward(self_pos, best)

        return step_away(self_pos, opp_pos)

    resources = get_xy_list(observation.get("resources", []))
    if resources:
        best = min(resources, key=lambda c: manhattan(c, self_pos))
        return step_toward(self_pos, best)

    enemy_resources = get_xy_list(observation.get("resource_positions", []))
    if enemy_resources:
        best = min(enemy_resources, key=lambda c: manhattan(c, self_pos))
        return step_toward(self_pos, best)

    return step_toward(self_pos, opp_pos)

